INSERT INTO public.modules (slug, code, track_id, title, title_ar, summary, summary_ar, external_url, position) VALUES ('sonoff-scene-design-hvac-troubleshooting', 'M17', 'sonoff-installer-certification', 'Scene Design, HVAC Integration & Systematic Troubleshooting', 'تصميم المشاهد ودمج التكييف واستكشاف الأعطال المنهجي', 'Designing scenes and routines households actually use, integrating thermostats with different HVAC system types, systematic fault diagnosis, and effective customer handover training.', 'تصميم مشاهد وروتينات تستخدمها الأسر فعليًا، دمج الترموستات مع أنواع أنظمة تكييف مختلفة، التشخيص المنهجي للأعطال، وتدريب تسليم فعّال للعميل.', NULL, 17);
INSERT INTO public.lessons (module_id, title, title_ar, content, content_ar, position) SELECT id, 'Scene & Routine Design for Real Households', 'تصميم المشاهد والروتينات للأسر الحقيقية', 'A scene groups multiple device actions under one trigger (a button press, a voice command, or a time), while a routine typically chains scenes and conditions together across a day. The most common design mistake is over-automating: giving every light and plug its own trigger creates a system nobody can predict. Instead, group devices by how a room is actually used — a ''movie night'' scene should adjust lighting, not touch the kitchen — and always keep one obvious manual override (a physical switch or a single app button) that instantly cancels any active scene.', 'يجمع المشهد عدة إجراءات لأجهزة متعددة تحت محفز واحد (ضغطة زر، أمر صوتي، أو وقت)، بينما الروتين عادة يسلسل مشاهد وشروطًا معًا عبر اليوم. أكثر خطأ تصميم شائع هو الإفراط في الأتمتة: إعطاء كل ضوء ومقبس محفزه الخاص يخلق نظامًا لا يستطيع أحد التنبؤ به. بدلًا من ذلك، جمّع الأجهزة حسب كيفية استخدام الغرفة فعليًا — مشهد ''ليلة الفيلم'' يجب أن يضبط الإضاءة، لا يلمس المطبخ — واحتفظ دائمًا بتجاوز يدوي واضح (مفتاح فعلي أو زر واحد في التطبيق) يلغي فورًا أي مشهد نشط.', 1 FROM public.modules WHERE slug = 'sonoff-scene-design-hvac-troubleshooting';
INSERT INTO public.lessons (module_id, title, title_ar, content, content_ar, position) SELECT id, 'Integrating Thermostats & HVAC Control Points', 'دمج الترموستات ونقاط التحكم بالتكييف', 'Before connecting any smart thermostat control point to an HVAC system, identify the system type (conventional forced-air, heat pump, boiler, mini-split) since control wiring and staging differ significantly between them. Heat pumps in particular need correct auxiliary/emergency heat wiring to avoid inefficient operation in cold weather. After wiring, always run a full cycle test — heat, cool, and fan-only — before leaving the site, since a miswired common wire is one of the most frequent causes of a system that ''looks'' connected but doesn''t actually control the equipment.', 'قبل توصيل أي نقطة تحكم ترموستات ذكي بنظام تكييف، حدد نوع النظام (هواء قسري تقليدي، مضخة حرارية، غلاية، مصغّر) لأن توصيلات التحكم والمراحل تختلف بشكل كبير بينها. المضخات الحرارية خصوصًا تحتاج توصيل تدفئة مساعدة/طوارئ صحيح لتجنب تشغيل غير فعّال في الطقس البارد. بعد التوصيل، شغّل دائمًا اختبار دورة كاملة — تدفئة وتبريد ومروحة فقط — قبل مغادرة الموقع، لأن توصيل سلك مشترك خاطئ من أكثر أسباب نظام ''يبدو'' متصلًا لكنه لا يتحكم فعليًا بالمعدات.', 2 FROM public.modules WHERE slug = 'sonoff-scene-design-hvac-troubleshooting';
INSERT INTO public.lessons (module_id, title, title_ar, content, content_ar, position) SELECT id, 'Systematic Troubleshooting: From Symptom to Root Cause', 'استكشاف الأعطال المنهجي: من العرض إلى السبب الجذري', 'When a customer reports ''the lights stopped working,'' resist fixing the first thing that looks wrong. Work through layers systematically: confirm power at the device, confirm network connectivity (is the device reachable at all, or just unresponsive to automations), confirm the automation/scene logic itself hasn''t changed, and only then look at the app or cloud service. Logging what layer the fault was actually found in — power, network, logic, or cloud — builds a pattern over time that speeds up diagnosis on repeat visits to the same site.', 'عندما يُبلغ العميل بأن ''الأضواء توقفت عن العمل''، قاوم إصلاح أول شيء يبدو خاطئًا. اعمل عبر الطبقات بشكل منهجي: تأكد من وصول الكهرباء للجهاز، تأكد من اتصال الشبكة (هل الجهاز قابل للوصول أصلًا، أم فقط غير مستجيب للأتمتة)، تأكد من أن منطق الأتمتة/المشهد نفسه لم يتغير، وعندها فقط انظر إلى التطبيق أو الخدمة السحابية. تسجيل الطبقة التي وُجد فيها العطل فعليًا — الكهرباء أو الشبكة أو المنطق أو السحابة — يبني نمطًا بمرور الوقت يسرّع التشخيص في الزيارات المتكررة لنفس الموقع.', 3 FROM public.modules WHERE slug = 'sonoff-scene-design-hvac-troubleshooting';
INSERT INTO public.lessons (module_id, title, title_ar, content, content_ar, position) SELECT id, 'Customer Training: Handover That Actually Sticks', 'تدريب العميل: تسليم يبقى أثره فعليًا', 'A technically perfect installation fails if the customer doesn''t understand how to use it. Effective handover training covers three things in order: what happens automatically (so they don''t fight the system), how to manually override anything (so they never feel stuck), and who to contact and what information to have ready if something breaks (device name, approximate time it stopped working, what they were trying to do). A one-page printed or digital cheat sheet left with the customer outperforms a verbal walkthrough alone.', 'التركيب المثالي تقنيًا يفشل إذا لم يفهم العميل كيفية استخدامه. تدريب التسليم الفعّال يغطي ثلاثة أمور بالترتيب: ما يحدث تلقائيًا (حتى لا يقاوم النظام)، كيفية التجاوز اليدوي لأي شيء (حتى لا يشعر بالعجز أبدًا)، ومن يتصل به وما المعلومات التي يجب تجهيزها إذا تعطل شيء (اسم الجهاز، الوقت التقريبي لتوقفه، ما كان يحاول فعله). ورقة تلخيص مطبوعة أو رقمية واحدة تُترك مع العميل تتفوق على شرح شفهي وحده.', 4 FROM public.modules WHERE slug = 'sonoff-scene-design-hvac-troubleshooting';
INSERT INTO public.quizzes (module_id, tier, title, title_ar, pass_percent) SELECT id, 'bronze', title || ' — Bronze Quiz', title_ar || ' — اختبار برونزي', 80 FROM public.modules WHERE slug = 'sonoff-scene-design-hvac-troubleshooting';
