INSERT INTO public.quiz_options (question_id, option_text, option_text_ar, is_correct, position) SELECT qq.id, 'Using too few triggers per scene', 'استخدام محفزات قليلة جدًا لكل مشهد', FALSE, 2 FROM public.quiz_questions qq JOIN public.quizzes q ON q.id = qq.quiz_id JOIN public.modules m ON m.id = q.module_id WHERE m.slug = 'sonoff-scene-design-hvac-troubleshooting' AND q.tier = 'bronze' AND qq.question = 'What is the most common mistake when designing household automation scenes?';
INSERT INTO public.quiz_options (question_id, option_text, option_text_ar, is_correct, position) SELECT qq.id, 'Naming scenes in Arabic instead of English', 'تسمية المشاهد بالعربية بدلًا من الإنجليزية', FALSE, 3 FROM public.quiz_questions qq JOIN public.quizzes q ON q.id = qq.quiz_id JOIN public.modules m ON m.id = q.module_id WHERE m.slug = 'sonoff-scene-design-hvac-troubleshooting' AND q.tier = 'bronze' AND qq.question = 'What is the most common mistake when designing household automation scenes?';
INSERT INTO public.quiz_questions (quiz_id, question, question_ar, position) SELECT q.id, 'Why is a full heat/cool/fan-only cycle test essential after wiring a smart thermostat?', 'لماذا يُعد اختبار دورة كامل (تدفئة/تبريد/مروحة فقط) ضروريًا بعد توصيل ترموستات ذكي؟', 2 FROM public.quizzes q JOIN public.modules m ON m.id = q.module_id WHERE m.slug = 'sonoff-scene-design-hvac-troubleshooting' AND q.tier = 'bronze';
INSERT INTO public.quiz_options (question_id, option_text, option_text_ar, is_correct, position) SELECT qq.id, 'A miswired common wire can make the system look connected without actually controlling the equipment', 'توصيل سلك مشترك خاطئ قد يجعل النظام يبدو متصلًا دون التحكم فعليًا بالمعدات', TRUE, 1 FROM public.quiz_questions qq JOIN public.quizzes q ON q.id = qq.quiz_id JOIN public.modules m ON m.id = q.module_id WHERE m.slug = 'sonoff-scene-design-hvac-troubleshooting' AND q.tier = 'bronze' AND qq.question = 'Why is a full heat/cool/fan-only cycle test essential after wiring a smart thermostat?';
INSERT INTO public.quiz_options (question_id, option_text, option_text_ar, is_correct, position) SELECT qq.id, 'It''s only needed to check the app''s color scheme', 'يُحتاج فقط للتحقق من نظام ألوان التطبيق', FALSE, 2 FROM public.quiz_questions qq JOIN public.quizzes q ON q.id = qq.quiz_id JOIN public.modules m ON m.id = q.module_id WHERE m.slug = 'sonoff-scene-design-hvac-troubleshooting' AND q.tier = 'bronze' AND qq.question = 'Why is a full heat/cool/fan-only cycle test essential after wiring a smart thermostat?';
INSERT INTO public.quiz_options (question_id, option_text, option_text_ar, is_correct, position) SELECT qq.id, 'Cycle testing is optional and rarely useful', 'اختبار الدورة اختياري ونادرًا ما يكون مفيدًا', FALSE, 3 FROM public.quiz_questions qq JOIN public.quizzes q ON q.id = qq.quiz_id JOIN public.modules m ON m.id = q.module_id WHERE m.slug = 'sonoff-scene-design-hvac-troubleshooting' AND q.tier = 'bronze' AND qq.question = 'Why is a full heat/cool/fan-only cycle test essential after wiring a smart thermostat?';
